use teaql_runtime::*;
use serde_json::{json,Value as J};
use std::{collections::BTreeMap,io::{self,BufRead},sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}},future::Future,pin::Pin,task::{Context,Poll,Wake,Waker},panic::{catch_unwind,AssertUnwindSafe}};
fn model(j:&J)->J{let mut op=RuntimeOperation::new(j["family"].as_str().unwrap(),j["name"].as_str().unwrap());for a in j["attributes"].as_array().unwrap(){let v=match a["kind"].as_str().unwrap(){"string"=>RuntimeAttributeValue::String(a["value"].as_str().unwrap().into()),"bool"=>RuntimeAttributeValue::Boolean(a["value"].as_bool().unwrap()),"u64"=>RuntimeAttributeValue::from(a["value"].as_str().unwrap().parse::<usize>().unwrap()),"float"=>RuntimeAttributeValue::Float(f64::from_bits(u64::from_str_radix(a["value"].as_str().unwrap(),16).unwrap())),_=>RuntimeAttributeValue::Integer(a["value"].as_str().unwrap().parse().unwrap())};op=op.attribute(a["key"].as_str().unwrap(),v);}let attrs=op.attributes.iter().map(|(k,v)|(k.clone(),match v{RuntimeAttributeValue::String(s)=>json!({"kind":"string","value":s}),RuntimeAttributeValue::Integer(i)=>json!({"kind":"integer","value":i.to_string()}),RuntimeAttributeValue::Float(f)=>json!({"kind":"float","value":format!("{:016x}",f.to_bits())}),RuntimeAttributeValue::Boolean(b)=>json!({"kind":"bool","value":b})})).collect::<BTreeMap<_,_>>();json!({"family":op.family,"name":op.name,"attributes":attrs,"categories":j["errors"].as_array().unwrap().iter().map(|e|runtime_error_category(e.as_str().unwrap())).collect::<Vec<_>>()})}
#[derive(Default)]struct Shared{notes:Mutex<Vec<String>>,active:AtomicBool}
impl Shared{fn note(&self,n:&str){self.notes.lock().unwrap().push(n.into());}}
struct Guard(Arc<Shared>);impl Drop for Guard{fn drop(&mut self){self.0.active.store(false,Ordering::SeqCst);self.0.note("leave");}}
fn activate(s:&Arc<Shared>,b:&str,cb:&mut dyn FnMut()){s.note("enter");s.active.store(true,Ordering::SeqCst);let _guard=Guard(s.clone());if b=="before"{panic!("adapter")}if b=="skip"{return}if b=="swallow"||b=="swallow_after"{let _=catch_unwind(AssertUnwindSafe(cb));if b=="swallow_after"{panic!("adapter")}return}cb();if b=="twice"{cb()}if b=="after"{panic!("adapter")}}
struct Scope{state:Arc<Shared>,behavior:String,fail:bool}impl Drop for Scope{fn drop(&mut self){self.state.note("scope.drop");}}
impl RuntimeTelemetryScope for Scope{fn with_context(&self,cb:&mut dyn FnMut()){activate(&self.state,&self.behavior,cb)}fn success(&mut self,_:BTreeMap<String,RuntimeAttributeValue>){self.state.note("success");if self.fail{panic!("finish")}}fn failure(&mut self,t:&str){self.state.note(t);if self.fail{panic!("finish")}}}
struct Prop{state:Arc<Shared>,behavior:String}impl Drop for Prop{fn drop(&mut self){self.state.note("prop.drop");}}impl RuntimeTelemetryPropagationContext for Prop{fn with_context(&self,cb:&mut dyn FnMut()){activate(&self.state,&self.behavior,cb)}}
struct Adapter{state:Arc<Shared>,behavior:String,create_fail:bool,finish_fail:bool}impl RuntimeTelemetry for Adapter{fn start(&self,_:RuntimeOperation)->Box<dyn RuntimeTelemetryScope>{self.state.note("start");if self.create_fail{panic!("create")}Box::new(Scope{state:self.state.clone(),behavior:self.behavior.clone(),fail:self.finish_fail})}fn extract_context(&self,_:&BTreeMap<String,String>)->Box<dyn RuntimeTelemetryPropagationContext>{self.state.note("extract");if self.create_fail{panic!("create")}Box::new(Prop{state:self.state.clone(),behavior:self.behavior.clone()})}}
struct Raw{state:Arc<Shared>,sequence:Vec<String>,count:usize}impl Future for Raw{type Output=usize;fn poll(mut self:Pin<&mut Self>,cx:&mut Context<'_>)->Poll<usize>{let index=self.count;self.count+=1;self.state.note(&format!("poll:{}:{}",self.count,if self.state.active.load(Ordering::SeqCst){"inside"}else{"outside"}));match self.sequence[index.min(self.sequence.len()-1)].as_str(){"panic"=>panic!("business"),"pending"=>{cx.waker().wake_by_ref();Poll::Pending},_=>Poll::Ready(self.count)}}}impl Drop for Raw{fn drop(&mut self){self.state.note("future.drop");}}
struct WakeNothing;impl Wake for WakeNothing{fn wake(self:Arc<Self>) {}}
fn drive<F:Future<Output=usize>>(f:F,polls:usize)->J{let waker=Waker::from(Arc::new(WakeNothing));let mut cx=Context::from_waker(&waker);let mut f=Box::pin(f);let mut out=vec![];for _ in 0..polls{match catch_unwind(AssertUnwindSafe(||f.as_mut().poll(&mut cx))){Ok(Poll::Pending)=>out.push(J::Null),Ok(Poll::Ready(v))=>{out.push(json!({"ready":v.to_string()}));break},Err(p)=>{let msg=p.downcast_ref::<&str>().copied().unwrap_or("unknown");out.push(json!({"panic":msg}));break}}}json!(out)}
fn raw(state:&Arc<Shared>,a:&J)->Raw{Raw{state:state.clone(),sequence:a["sequence"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().into()).collect(),count:0}}
fn flow(j:&J)->J{let state=Arc::new(Shared::default());let telemetry:Arc<dyn RuntimeTelemetry>=if j["noop"]==true{Arc::new(NoopRuntimeTelemetry)}else{Arc::new(Adapter{state:state.clone(),behavior:j["behavior"].as_str().unwrap().into(),create_fail:j["create_fail"]==true,finish_fail:j["finish_fail"]==true})};let noop=telemetry.is_noop();let mut results=vec![];if j["propagation"]==true{let scope=extract_runtime_context(&telemetry,&BTreeMap::new());for a in j["actions"].as_array().unwrap(){if a["op"]=="run"{results.push(drive(scope.run(raw(&state,a)),a["polls"].as_str().unwrap().parse().unwrap()))}}}else{let scope=start_runtime_operation(&telemetry,RuntimeOperation::new("query","Order.list"));for a in j["actions"].as_array().unwrap(){match a["op"].as_str().unwrap(){"run"=>results.push(drive(scope.run(raw(&state,a)),a["polls"].as_str().unwrap().parse().unwrap())),"success"=>scope.success(BTreeMap::new()),_=>scope.failure("native_error")}}}let notes=state.notes.lock().unwrap().clone();json!({"notes":notes,"results":results,"noop":noop})}
fn main(){std::panic::set_hook(Box::new(|_|{}));for line in io::stdin().lock().lines(){let j:J=serde_json::from_str(&line.unwrap()).unwrap();println!("{}",if j["mode"]=="model"{model(&j)}else{flow(&j)});}}
